/// <summary>
/// Override to enable attribute based pricing for vendor rebates
/// </summary>
/// <param name = "_rebateDeal">Rebate deal record</param>
/// <returns></returns>
public static boolean isGUPCustomerRebate(TAMRebateDeal _rebateDeal)
{
    boolean ret = next isGUPCustomerRebate(_rebateDeal);

    ret = GUPGlobalEnableFeatureHelper::useAttributeBasedPricing()
        && (_rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Cust
        || _rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend);

    return ret;
}

/// <summary>
/// Convert PurchLine to SalesLine for rebate matching
/// </summary>
/// <param name = "_purchLine"><t>PurchLine</t> table buffer</param>
/// <returns><t>SalesLine</t> table buffer</returns>
public static SalesLine purchLineToSalesLine(PurchLine _purchLine)
{
    SalesLine salesLine;

    if (_purchLine)
    {
        salesLine.clear();
        salesLine.ItemId = _purchLine.ItemId;
        salesLine.InventTransId = _purchLine.InventTransId;
        salesLine.SalesQty = _purchLine.PurchQty;
        salesLine.InventDimId = _purchLine.InventDimId;
        salesLine.SalesPrice = _purchLine.PurchPrice;
        salesLine.CurrencyCode = _purchLine.CurrencyCode;
        salesLine.LineAmount = _purchLine.LineAmount;
    }

    return salesLine;
}

/// <summary>
/// Bug 286663: CB705- Vendor deals are not filtering based on the header vendor account
/// Convert VendPackingSlipTrans to SalesLine for rebate matching
/// </summary>
/// <param name = "_vendPackingSlipTrans"><t>VendPackingSlipTrans</t> table buffer</param>
/// <returns><t>SalesLine</t> table buffer</returns>
public static SalesLine vendPackingSlipTransToSalesLine(VendPackingSlipTrans _vendPackingSlipTrans)
{
    SalesLine salesLine;

    if (_vendPackingSlipTrans)
    {
        PurchLine purchLine = _vendPackingSlipTrans.purchLine();

        salesLine.clear();
        salesLine.ItemId = _vendPackingSlipTrans.ItemId;
        salesLine.InventTransId = _vendPackingSlipTrans.InventTransId;
        salesLine.SalesQty = _vendPackingSlipTrans.Qty;
        salesLine.InventDimId = _vendPackingSlipTrans.InventDimId;
        salesLine.SalesPrice = purchLine.PurchPrice;
        salesLine.CurrencyCode = purchLine.CurrencyCode;
        salesLine.LineAmount = purchLine.LineAmount;
    }

    return salesLine;
}

/// <summary>
/// Bug 286663: CB705- Vendor deals are not filtering based on the header vendor account
/// Convert VendPackingSlipTrans to SalesLine for rebate matching
/// </summary>
/// <param name = "_vendPackingSlipTrans"><t>VendPackingSlipTrans</t> table buffer</param>
/// <returns><t>SalesLine</t> table buffer</returns>
public static SalesLine vendInvoiceTransToSalesLine(VendInvoiceTrans _vendInvoiceTrans)
{
    SalesLine salesLine;

    if (_vendInvoiceTrans)
    {            
        salesLine.clear();
        salesLine.ItemId = _vendInvoiceTrans.ItemId;
        salesLine.InventTransId = _vendInvoiceTrans.InventTransId;
        salesLine.SalesQty = _vendInvoiceTrans.Qty;
        salesLine.InventDimId = _vendInvoiceTrans.InventDimId;
        salesLine.SalesPrice = _vendInvoiceTrans.PurchPrice;
        salesLine.CurrencyCode = _vendInvoiceTrans.CurrencyCode;
        salesLine.LineAmount = _vendInvoiceTrans.LineAmount;
    }

    return salesLine;
}

/// <summary>
/// Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
/// Convert METRebateScanSupplierTable to SalesLine for rebate matching
/// </summary>
/// <param name = "_purchLine"><t>METRebateScanSupplierTable</t> table buffer</param>
/// <returns><t>SalesLine</t> table buffer</returns>
public static SalesLine externalDataToSalesLine(METRebateScanSupplierTable _externalSalesData)
{
    SalesLine salesLine;

    if (_externalSalesData)
    {
        salesLine.clear();
        salesLine.ItemId = _externalSalesData.ItemId;
        salesLine.InventTransId = _externalSalesData.TransactionNumber;
        salesLine.SalesQty = _externalSalesData.SalesQty;
        salesLine.InventDimId = InventDim::findOrCreateBlank().inventDimId;
        salesLine.SalesPrice = _externalSalesData.SalesValue; // Same?
        salesLine.CurrencyCode = _externalSalesData.CurrencyCode;
        salesLine.LineAmount = _externalSalesData.SalesValue;
    }

    return salesLine;
}

/// <summary>
/// Override to handle vendor rebates with purch lines
/// </summary>
/// <param name = "_journalTransaction">Transaction table record based on which the rebate is calculated</param>
/// <param name = "_rebateQueryBuilder">Rebate deal query based on setup</param>
/// <param name = "_rebateDate">Rebate effective date</param>
/// <param name = "_rebateTable"><t>TAMRebateTable</t> table buffer</param>
/// <returns>true, if a matching rebate deal is found otherwise false</returns>
public static boolean checkIfPricingAttributesAreMatched(
    Common _journalTransaction,
    TAMRebateQueryBuilder _rebateQueryBuilder,
    TAMRebateDate _rebateDate,
    TAMRebateTable _rebateTable)
{
    PurchLine purchLine;
    VendPackingSlipTrans vendPackingSlipTrans;
    VendInvoiceTrans vendInvoiceTrans;
    // Bug 294039: CB705- Rebate is not calculating when vendor deal is based on sales orders
    // vendor deals can be configured with supplier rebate basis = sales orders
    boolean isVendorRebate = _rebateTable.ModuleInventCustVend == ModuleInventCustVend::Vend && _rebateTable.RebateBasisVend == TAMRebateBasisVend::Purch;
    METRebateScanSupplierTable rebateScanSupplierTable;

    SalesTable salesTable;

    // Bug 303761: CB705 - Cannot process external sales data file from vendor rebate
    boolean isRebateScanSupplierTable = _journalTransaction is METRebateScanSupplierTable;

    // If vendor rebate and source is ordered, first retain the purch line details and pass a dummy sales table buffer to bypass the standard check
    if (isVendorRebate && !isRebateScanSupplierTable)
    {
        if (_journalTransaction is PurchLine)
        {
            //Preserve purch line details
            purchLine = _journalTransaction as PurchLine;
            //_journalTransaction = salesTable;
        }
        // Bug 286663: CB705- Vendor deals are not filtering based on the header vendor account
        else if (_journalTransaction is VendPackingSlipTrans)
        {
            vendPackingSlipTrans = _journalTransaction as VendPackingSlipTrans;
        }
        else if (_journalTransaction is VendInvoiceTrans)
        {
            vendInvoiceTrans = _journalTransaction as VendInvoiceTrans;
        }

        _journalTransaction = salesTable;
    }
    // Bug 298212: CB201 - Error during Provisioning of Customer Rebate Deal (By Line) without Batch Job
    // moved it outside if isVendorRebate to bypass the error trying to find SalesId field against METRebateScanSupplierTable
    // external data rebate have a validation so that no filter is entered for attribute with source SalesLine or SalesTable
    if (isRebateScanSupplierTable)
    {
        rebateScanSupplierTable = _journalTransaction as METRebateScanSupplierTable;
        _journalTransaction = salesTable;
    }

    boolean ret = next checkIfPricingAttributesAreMatched(
        _journalTransaction,
        _rebateQueryBuilder,
        _rebateDate,
        _rebateTable);

    if (!ret && isVendorRebate && !isRebateScanSupplierTable)
    {
        if (GUPGlobalEnableFeatureHelper::isPricingRuleHashFeatureEnabled())
        {
            SalesLine salesLine;

            if (purchLine)
            {
                //Convert purch line to sales line for attribute matching
                salesLine = GUPRebateMatchingHelper::purchLineToSalesLine(purchLine);
            }
            // Bug 286663: CB705- Vendor deals are not filtering based on the header vendor account
            else if (vendPackingSlipTrans)
            {
                salesLine = GUPRebateMatchingHelper::vendPackingSlipTransToSalesLine(vendPackingSlipTrans);
            }
            else if (vendInvoiceTrans)
            {
                salesLine = GUPRebateMatchingHelper::vendInvoiceTransToSalesLine(vendInvoiceTrans);
            }

            TableName tableName = tableStr(SalesLine);

            //Call the hash based matching method with the converted sales line
            ret = GUPRebateMatchingHelper::checkIfPricingAttributesAreMatchedForSalesByHash(salesTable, salesLine, tableName, _rebateTable);
        }

    }

    //Bug 317464 - Vendor rebate with sales basis not working
    if (!ret && _rebateTable.ModuleInventCustVend == ModuleInventCustVend::Vend && _rebateTable.RebateBasisVend == TAMRebateBasisVend::Sales && _journalTransaction is CustInvoiceTrans)
    {
        //Bug 317464 - Vendor rebate with sales basis not working
        CustInvoiceTrans custInvoiceTrans;
        CustInvoiceJour custInvoiceJour;

        custInvoiceTrans = _journalTransaction as custInvoiceTrans;
        if (custInvoiceTrans)
        {
            SalesLine salesLine;

            custInvoiceJour = custInvoiceTrans.custInvoiceJour();
            salesTable = custInvoiceJour.salesTable();
            salesLine = custInvoiceTrans.salesLine();

            TableName tableName = tableStr(SalesLine);

            ret = GUPRebateMatchingHelper::checkIfPricingAttributesAreMatchedForSalesByHash(salesTable, salesLine, tableName, _rebateTable);
        }
    }

    // Bug 298212: CB201 - Error during Provisioning of Customer Rebate Deal (By Line) without Batch Job
    // Not required to call checkIfPricingAttributesAreMatchedForSalesByHash, customer and product filters are done upfront when building the query in TAMRebateQueryBuilder_GlobalUnifiedPricing_Extension\buildCalculateAmountQuery
    // external data rebate have a validation so that no filter is entered for attribute with source SalesLine or SalesTable
    if (!ret && isRebateScanSupplierTable)
    {
        ret = true;
    }

    return ret;
}
